  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "zone_id" bigint NOT NULL,
  "type" text NOT NULL,
  "name" text NOT NULL,
  "content" text NOT NULL,
  "ttl" int NOT NULL DEFAULT 300,
  "priority" int,
  "proxied" boolean NOT NULL DEFAULT false,
  "external_id" text,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "upload_sessions" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "user_id" bigint NOT NULL,
  "hosting_account_id" bigint NOT NULL,
  "target_path" text NOT NULL,
  "size_bytes" bigint NOT NULL,
  "received_bytes" bigint NOT NULL DEFAULT 0,
  "overwrite" boolean NOT NULL DEFAULT false,
  "status" text NOT NULL DEFAULT 'receiving',
  "job_id" bigint,
  "expires_at" timestamptz NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "file_operations" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "hosting_account_id" bigint NOT NULL,
  "user_id" bigint,
  "op" text NOT NULL,
  "paths" jsonb NOT NULL DEFAULT ('[]'::jsonb),
  "target" text,
  "status" text NOT NULL DEFAULT 'succeeded',
  "job_id" bigint,
  "error_code" text,
  "created_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "terminal_sessions" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "user_id" bigint NOT NULL,
  "server_id" bigint NOT NULL,
  "hosting_account_id" bigint,
  "unix_uid" int NOT NULL,
  "mode" text NOT NULL DEFAULT 'account',
  "started_at" timestamptz NOT NULL DEFAULT (now()),
  "ended_at" timestamptz,
  "ended_reason" text,
  "recording_ref" text
);

CREATE TABLE "wordpress_sites" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "website_id" bigint UNIQUE NOT NULL,
  "hosting_account_id" bigint NOT NULL,
  "path" text NOT NULL,
  "version" text,
  "admin_user" text,
  "multisite" boolean NOT NULL DEFAULT false,
  "state" text NOT NULL DEFAULT 'ok',
  "auto_update" text NOT NULL DEFAULT 'minor',
  "update_window" text NOT NULL DEFAULT '02:00-05:00',
  "maintenance" boolean NOT NULL DEFAULT false,
  "hardening" jsonb NOT NULL DEFAULT ('{}'::jsonb),
  "staging_of_id" bigint,
  "checksums_ok" boolean,
  "last_scan_at" timestamptz,
  "last_update_at" timestamptz,
  "database_id" bigint,
  "last_auto_update_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  "deleted_at" timestamptz
);

CREATE TABLE "wordpress_components" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "wordpress_site_id" bigint NOT NULL,
  "type" text NOT NULL,
  "slug" text,
  "name" text NOT NULL,
  "version" text NOT NULL,
  "update_version" text,
  "active" boolean NOT NULL DEFAULT true,
  "observed_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "wordpress_updates" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "wordpress_site_id" bigint NOT NULL,
  "job_id" bigint,
  "trigger" text NOT NULL DEFAULT 'manual',
  "items" jsonb NOT NULL DEFAULT ('[]'::jsonb),
  "steps" jsonb NOT NULL DEFAULT ('[]'::jsonb),
  "state" text NOT NULL DEFAULT 'running',
  "snapshot_id" bigint,
  "error" text,
  "requested_by_user_id" bigint,
  "started_at" timestamptz,
  "finished_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "git_repositories" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "website_id" bigint UNIQUE NOT NULL,
  "repo_url" text NOT NULL,
  "branch" text NOT NULL DEFAULT 'main',
  "deploy_key_public" text NOT NULL,
  "deploy_key_fingerprint" text NOT NULL,
  "webhook_secret_encrypted" bytea NOT NULL,
  "webhook_token" text UNIQUE NOT NULL,
  "auto_deploy" boolean NOT NULL DEFAULT false,
  "build_command" text,
  "shared_paths" jsonb NOT NULL DEFAULT ('[]'::jsonb),
  "keep_releases" int NOT NULL DEFAULT 5,
  "current_deployment_id" bigint,
  "spec_version" int NOT NULL DEFAULT 1,
  "observed_version" int NOT NULL DEFAULT 0,
  "status" text NOT NULL DEFAULT 'pending',
  "observed_facts" jsonb NOT NULL DEFAULT ('{}'::jsonb),
  "drift" jsonb,
  "observed_at" timestamptz,
  "last_job_id" bigint,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  "deleted_at" timestamptz
);

CREATE TABLE "git_deployments" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "git_repository_id" bigint NOT NULL,
  "commit_sha" text NOT NULL,
  "commit_message" text,
  "commit_author" text,
  "trigger" text NOT NULL,
  "state" text NOT NULL DEFAULT 'queued',
  "release_path" text,
  "rollback_of_id" bigint,
  "job_id" bigint,
  "requested_by_user_id" bigint,
  "started_at" timestamptz,
  "finished_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "docker_hosts" (
  "server_id" bigint PRIMARY KEY,
  "enabled" boolean NOT NULL DEFAULT false,
  "state" text NOT NULL DEFAULT 'not_installed',
  "engine_version" text,
  "compose_version" text,
  "api_version" text,
  "daemon_config" jsonb NOT NULL DEFAULT ('{}'::jsonb),
  "checks" jsonb NOT NULL DEFAULT ('[]'::jsonb),
  "port_range_from" int NOT NULL DEFAULT 20000,
  "port_range_to" int NOT NULL DEFAULT 29999,
  "firewall_synced_at" timestamptz,
  "observed_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "registries" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "name" text UNIQUE NOT NULL,
  "url" text NOT NULL,
  "username" text,
  "password_encrypted" bytea,
  "last_test_at" timestamptz,
  "last_test_ok" boolean,
  "last_test_message" text,
  "created_by_user_id" bigint,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  "deleted_at" timestamptz
);

CREATE TABLE "compose_projects" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "server_id" bigint NOT NULL,
  "name" text NOT NULL,
  "run_state" text NOT NULL DEFAULT 'stopped',
  "template" text,
  "env_encrypted" bytea,
  "current_revision_id" bigint,
  "created_by_user_id" bigint,
  "spec_version" int NOT NULL DEFAULT 1,
  "observed_version" int NOT NULL DEFAULT 0,
  "status" text NOT NULL DEFAULT 'pending',
  "observed_facts" jsonb NOT NULL DEFAULT ('{}'::jsonb),
  "drift" jsonb,
  "observed_at" timestamptz,
  "last_job_id" bigint,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  "deleted_at" timestamptz
);

CREATE TABLE "compose_revisions" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "project_id" bigint NOT NULL,
  "number" int NOT NULL,
  "yaml" text NOT NULL,
  "validated_yaml" text,
  "validated_sha256" text,
  "ok" boolean NOT NULL DEFAULT false,
  "findings_count" int NOT NULL DEFAULT 0,
  "validation_report" jsonb,
  "overrides" jsonb NOT NULL DEFAULT ('[]'::jsonb),
  "created_by_user_id" bigint,
  "created_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "containers" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "server_id" bigint NOT NULL,
  "docker_id" text NOT NULL,
  "name" text NOT NULL,
  "image" text NOT NULL,
  "image_digest" text,
  "project_id" bigint,
  "service" text,
  "state" text,
  "health" text,
