  "immutable_days" int,
  "detected" jsonb,
  "ssh_public_key" text,
  "host_key_sha256" text,
  "enabled" boolean NOT NULL DEFAULT true,
  "last_check_at" timestamptz,
  "last_check_ok" boolean,
  "last_check_error" text,
  "recovery_kit_acknowledged_at" timestamptz,
  "recovery_kit_acknowledged_by_user_id" bigint,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  "deleted_at" timestamptz
);

CREATE TABLE "backup_repositories" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "destination_id" bigint NOT NULL,
  "server_id" bigint NOT NULL,
  "scope_type" text NOT NULL,
  "hosting_account_id" bigint,
  "path" text NOT NULL,
  "password_encrypted" bytea NOT NULL,
  "initialized_at" timestamptz,
  "size_bytes" bigint NOT NULL DEFAULT 0,
  "snapshots_count" int NOT NULL DEFAULT 0,
  "last_snapshot_at" timestamptz,
  "last_check_at" timestamptz,
  "last_check_ok" boolean,
  "quota_state" text NOT NULL DEFAULT 'ok',
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  "deleted_at" timestamptz
);

CREATE TABLE "backup_policies" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "name" text NOT NULL,
  "scope_type" text NOT NULL,
  "scope_id" bigint,
  "contents" text[] NOT NULL DEFAULT ('{files,databases}'),
  "excludes" text[] NOT NULL DEFAULT ('{}'),
  "schedule" text NOT NULL,
  "retention" jsonb NOT NULL DEFAULT ('{}'::jsonb),
  "enabled" boolean NOT NULL DEFAULT true,
  "last_run_at" timestamptz,
  "next_run_at" timestamptz,
  "last_status" text,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  "deleted_at" timestamptz
);

CREATE TABLE "backup_policy_destinations" (
  "policy_id" bigint NOT NULL,
  "destination_id" bigint NOT NULL,
  PRIMARY KEY ("policy_id", "destination_id")
);

CREATE TABLE "backup_jobs" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "policy_id" bigint,
  "job_id" bigint,
  "repository_id" bigint,
  "snapshot_id" bigint,
  "started_at" timestamptz,
  "finished_at" timestamptz,
  "status" text NOT NULL,
  "bytes_added" bigint,
  "files_new" int
);

CREATE TABLE "backup_snapshots" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "destination_id" bigint NOT NULL,
  "repository_id" bigint NOT NULL,
  "restic_snapshot_id" text NOT NULL,
  "scope_type" text NOT NULL,
  "scope_id" bigint,
  "hosting_account_id" bigint,
  "website_id" bigint,
  "databases" text[] NOT NULL DEFAULT ('{}'),
  "contents" text[] NOT NULL DEFAULT ('{}'),
  "tags" text[] NOT NULL DEFAULT ('{}'),
  "size_bytes" bigint,
  "panel_version" text,
  "meta" jsonb,
  "locked_until" timestamptz,
  "job_id" bigint,
  "taken_at" timestamptz NOT NULL,
  "verified_at" timestamptz
);

CREATE TABLE "backup_verifications" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "destination_id" bigint NOT NULL,
  "repository_id" bigint,
  "hosting_account_id" bigint,
  "snapshot_id" bigint,
  "kind" text NOT NULL,
  "state" text NOT NULL DEFAULT 'running',
  "read_data_percent" int,
  "files_checked" int,
  "mismatches" int NOT NULL DEFAULT 0,
  "error" text,
  "job_id" bigint,
  "started_at" timestamptz NOT NULL DEFAULT (now()),
  "finished_at" timestamptz
);

CREATE TABLE "restore_jobs" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "snapshot_id" bigint,
  "hosting_account_id" bigint,
  "target_type" text NOT NULL,
  "target_id" bigint,
  "target_server_id" bigint,
  "mode" text NOT NULL DEFAULT 'new',
  "items" text[] NOT NULL DEFAULT ('{}'),
  "job_id" bigint,
  "status" text NOT NULL DEFAULT 'queued',
  "result" jsonb,
  "error" text,
  "pre_restore_snapshot_id" bigint,
  "requested_by_user_id" bigint NOT NULL,
  "finished_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "jobs" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "type" text NOT NULL,
  "server_id" bigint,
  "resource_type" text,
  "resource_id" bigint,
  "requested_by_user_id" bigint,
  "idempotency_key" text,
  "state" text NOT NULL DEFAULT 'queued',
  "progress" smallint NOT NULL DEFAULT 0,
  "attempts" int NOT NULL DEFAULT 0,
  "max_attempts" int NOT NULL DEFAULT 3,
  "timeout_sec" int NOT NULL DEFAULT 600,
  "error_code" text,
  "error_message" text,
  "parent_job_id" bigint,
  "started_at" timestamptz,
  "finished_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "job_steps" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "job_id" bigint NOT NULL,
  "seq" int NOT NULL,
  "op" text NOT NULL,
  "op_id" text UNIQUE NOT NULL,
  "params_redacted" jsonb NOT NULL DEFAULT ('{}'::jsonb),
  "state" text NOT NULL DEFAULT 'pending',
  "attempts" int NOT NULL DEFAULT 0,
  "result" jsonb,
  "compensation_op" text,
  "started_at" timestamptz,
  "finished_at" timestamptz
);

CREATE TABLE "job_logs" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "job_id" bigint NOT NULL,
  "step_id" bigint,
  "level" text NOT NULL,
  "message" text NOT NULL,
  "at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "audit_logs" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "at" timestamptz NOT NULL DEFAULT (now()),
  "actor_user_id" bigint,
  "impersonator_user_id" bigint,
  "actor_ip" inet,
  "user_agent" text,
  "action" text NOT NULL,
  "resource_type" text,
  "resource_id" bigint,
  "server_id" bigint,
  "job_id" bigint,
  "changes" jsonb,
  "result" text NOT NULL DEFAULT 'success',
  "prev_hash" text,
  "hash" text,
  PRIMARY KEY ("id", "at")
) PARTITION BY RANGE ("at");

CREATE TABLE "security_events" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "server_id" bigint,
  "website_id" bigint,
  "type" text NOT NULL,
  "severity" text NOT NULL,
  "source_ip" inet,
  "message" text NOT NULL DEFAULT '',
  "details" jsonb,
  "acknowledged_by_user_id" bigint,
  "acknowledged_at" timestamptz,
  "at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "firewall_rules" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "server_id" bigint NOT NULL,
  "priority" int NOT NULL DEFAULT 100,
  "action" text NOT NULL,
  "direction" text NOT NULL DEFAULT 'in',
  "protocol" text NOT NULL DEFAULT 'tcp',
  "enabled" boolean NOT NULL DEFAULT true,
  "port_range" text,
  "source_cidr" cidr,
  "comment" text,
  "managed_by" text NOT NULL DEFAULT 'user',
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "malware_scans" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "server_id" bigint NOT NULL,
  "hosting_account_id" bigint,
  "website_id" bigint,
  "job_id" bigint,
  "status" text NOT NULL,
  "target" text NOT NULL DEFAULT '.',
  "engines" text[] NOT NULL DEFAULT ('{clamav,yara}'),
  "files_scanned" int,
  "findings_count" int,
  "started_at" timestamptz,
  "finished_at" timestamptz
);

CREATE TABLE "malware_findings" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "scan_id" bigint NOT NULL,
  "path" text NOT NULL,
  "signature" text NOT NULL,
  "engine" text NOT NULL,
  "sha256" text NOT NULL,
  "size" bigint NOT NULL DEFAULT 0,
  "found_at" timestamptz NOT NULL DEFAULT (now()),
  "action" text NOT NULL DEFAULT 'none'
);

CREATE TABLE "quarantine_items" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "finding_id" bigint,
  "hosting_account_id" bigint,
  "original_path" text NOT NULL,
  "stored_path" text NOT NULL,
  "sha256" text NOT NULL,
  "signature" text NOT NULL DEFAULT '',
  "size" bigint NOT NULL DEFAULT 0,
  "quarantined_at" timestamptz NOT NULL DEFAULT (now()),
  "restored_at" timestamptz
);

CREATE TABLE "fim_baselines" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "server_id" bigint NOT NULL,
  "path" text NOT NULL,
  "sha256" text NOT NULL,
  "mode" int,
  "owner" text,
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "firewall_applies" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "server_id" bigint NOT NULL,
  "target" text NOT NULL,
  "user_id" bigint,
  "client_ip" inet NOT NULL,
  "token_hash" text,
  "spec" jsonb NOT NULL DEFAULT ('{}'::jsonb),
  "previous" jsonb,
  "ruleset_sha256" text,
  "status" text NOT NULL DEFAULT 'pending_confirm',
  "deadline_at" timestamptz NOT NULL,
  "confirmed_at" timestamptz,
  "rolled_back_at" timestamptz,
  "job_id" bigint,
  "created_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "security_settings" (
  "server_id" bigint PRIMARY KEY,
  "ssh" jsonb NOT NULL DEFAULT ('{}'::jsonb),
  "fail2ban" jsonb NOT NULL DEFAULT ('{}'::jsonb),
  "audit_facts" jsonb,
  "audited_at" timestamptz,
  "score" int,
  "score_items" jsonb,
  "scored_at" timestamptz,
  "fim_baseline_at" timestamptz,
  "fim_checked_at" timestamptz,
  "waf_events_cursor" text,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "waf_settings" (
  "website_id" bigint PRIMARY KEY,
  "mode" text NOT NULL DEFAULT 'DetectionOnly',
  "paranoia_level" smallint NOT NULL DEFAULT 1,
  "rule_exclusions" int[] NOT NULL DEFAULT ('{}'),
  "detection_since" timestamptz,
  "auto_block" boolean NOT NULL DEFAULT false,
  "available" boolean NOT NULL DEFAULT true,
  "applied_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "waf_events" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "uuid" uuid NOT NULL DEFAULT (gen_random_uuid()),
  "at" timestamptz NOT NULL,
  "website_id" bigint NOT NULL,
  "rule_id" int NOT NULL,
  "severity" text NOT NULL,
  "action" text NOT NULL,
  "client_ip" inet,
  "method" text,
