  "message" text,
  PRIMARY KEY ("id", "at")
) PARTITION BY RANGE ("at");

CREATE TABLE "fim_changes" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "server_id" bigint NOT NULL,
  "path" text NOT NULL,
  "change" text NOT NULL,
  "old_sha256" text,
  "new_sha256" text,
  "mode" int,
  "owner" text,
  "detected_at" timestamptz NOT NULL DEFAULT (now()),
  "acknowledged_by_user_id" bigint,
  "acknowledged_at" timestamptz
);

CREATE TABLE "terminal_recordings" (
  "terminal_session_id" bigint PRIMARY KEY,
  "mode" text NOT NULL,
  "client_ip" inet,
  "stored_ref" text NOT NULL,
  "bytes" bigint NOT NULL DEFAULT 0,
  "width" int,
  "height" int,
  "truncated" boolean NOT NULL DEFAULT false,
  "created_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "notifications" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" bigint NOT NULL,
  "type" text NOT NULL,
  "title" text NOT NULL,
  "body" text,
  "data" jsonb,
  "read_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "notification_channels" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "type" text NOT NULL,
  "name" text UNIQUE NOT NULL,
  "config" jsonb NOT NULL DEFAULT ('{}'),
  "secret_encrypted" text,
  "enabled" boolean NOT NULL DEFAULT true,
  "created_by_user_id" bigint,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "notification_preferences" (
  "user_id" bigint NOT NULL,
  "event_type" text NOT NULL,
  "channels" text[] NOT NULL DEFAULT ('{in_app}'),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  PRIMARY KEY ("user_id", "event_type")
);

CREATE TABLE "notification_deliveries" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "channel_id" bigint NOT NULL,
  "alert_id" bigint,
  "event_type" text NOT NULL,
  "severity" text NOT NULL,
  "title" text NOT NULL,
  "payload" jsonb NOT NULL DEFAULT ('{}'),
  "state" text NOT NULL DEFAULT 'queued',
  "attempts" int NOT NULL DEFAULT 0,
  "error" text,
  "next_retry_at" timestamptz,
  "sent_at" timestamptz,
  "resend_of_id" bigint,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "settings" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "group_key" text NOT NULL,
  "key" text NOT NULL,
  "value" jsonb,
  "is_encrypted" boolean NOT NULL DEFAULT false,
  "updated_by_user_id" bigint,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "metric_samples" (
  "server_id" bigint NOT NULL,
  "hosting_account_id" bigint,
  "metric" text NOT NULL,
  "value" float8 NOT NULL,
  "at" timestamptz NOT NULL
) PARTITION BY RANGE ("at");

CREATE TABLE "metric_rollups" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "server_id" bigint NOT NULL,
  "hosting_account_id" bigint,
  "metric" text NOT NULL,
  "bucket" timestamptz NOT NULL,
  "min_value" float8 NOT NULL,
  "avg_value" float8 NOT NULL,
  "max_value" float8 NOT NULL,
  "samples" int NOT NULL
);

CREATE TABLE "alert_rules" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "name" text NOT NULL,
  "metric" text NOT NULL,
  "operator" text NOT NULL,
  "threshold" float8 NOT NULL,
  "duration_sec" int NOT NULL DEFAULT 300,
  "repeat_sec" int NOT NULL DEFAULT 14400,
  "severity" text NOT NULL DEFAULT 'medium',
  "scope_type" text NOT NULL DEFAULT 'server',
  "scope_id" bigint,
  "channels" text[] NOT NULL DEFAULT ('{in_app}'),
  "channel_ids" bigint[] NOT NULL DEFAULT ('{}'),
  "is_default" boolean NOT NULL DEFAULT false,
  "default_key" text UNIQUE,
  "enabled" boolean NOT NULL DEFAULT true,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "alerts" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "rule_id" bigint NOT NULL,
  "server_id" bigint,
  "hosting_account_id" bigint,
  "website_id" bigint,
  "fingerprint" text NOT NULL,
  "state" text NOT NULL,
  "severity" text NOT NULL,
  "value" float8,
  "message" text,
  "started_at" timestamptz NOT NULL,
  "firing_at" timestamptz,
  "resolved_at" timestamptz,
  "below_count" int NOT NULL DEFAULT 0,
  "acked_by_user_id" bigint,
  "acked_at" timestamptz,
  "silenced_until" timestamptz,
  "silence_reason" text,
  "last_notified_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "uptime_checks" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "website_id" bigint UNIQUE NOT NULL,
  "path" text NOT NULL DEFAULT '/',
  "keyword" text,
  "interval_sec" int NOT NULL DEFAULT 60,
  "enabled" boolean NOT NULL DEFAULT true,
  "state" text NOT NULL DEFAULT 'unknown',
  "consecutive_failures" int NOT NULL DEFAULT 0,
  "last_status" int,
  "last_latency_ms" int,
  "last_error" text,
  "last_checked_at" timestamptz,
  "down_since" timestamptz,
  "cert_expires_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "uptime_results" (
  "check_id" bigint NOT NULL,
  "ok" boolean NOT NULL,
  "status" int,
  "latency_ms" int,
  "error" text,
  "at" timestamptz NOT NULL
) PARTITION BY RANGE ("at");

