COMMENT ON TABLE "users" IS 'Người dùng. realm=admin: SUPER_ADMIN/ADMIN; realm=portal: USER (D-25, D-40).';

COMMENT ON COLUMN "users"."realm" IS 'admin | portal — bất biến (trigger)';

COMMENT ON COLUMN "users"."password_hash" IS 'argon2id';

COMMENT ON COLUMN "users"."status" IS 'active|locked|disabled';

COMMENT ON COLUMN "roles"."key" IS 'SUPER_ADMIN|ADMIN|USER';

COMMENT ON COLUMN "permissions"."key" IS 'vd websites.create';

COMMENT ON COLUMN "user_roles"."user_id" IS 'v0.x: 1 vai trò/user';

COMMENT ON TABLE "user_scopes" IS 'Phạm vi được giao cho ADMIN.';

COMMENT ON COLUMN "user_scopes"."scope_type" IS 'server|hosting_account';

COMMENT ON COLUMN "mfa_credentials"."type" IS 'totp|webauthn|recovery';

COMMENT ON TABLE "api_tokens" IS 'Token nội bộ (automation, CLI). Không có Public Provisioning API (DEFERRED).';

COMMENT ON COLUMN "servers"."role_tags" IS 'web|db|backup|docker|control-plane';

COMMENT ON COLUMN "servers"."spec_version" IS 'Desired: tăng mỗi lần đổi cấu hình';

COMMENT ON COLUMN "servers"."observed_version" IS 'Observed: phiên bản agent đã áp dụng';

COMMENT ON COLUMN "servers"."status" IS 'pending|provisioning|ready|degraded|failed|suspended|deleting';

COMMENT ON COLUMN "agents"."transport" IS 'local|mtls';

COMMENT ON TABLE "agent_enrollment_tokens" IS 'Token join node dùng một lần (D-90).';

COMMENT ON COLUMN "agent_enrollment_tokens"."token_hash" IS 'sha256 của token 32 byte; token chỉ hiện một lần (D-90)';

COMMENT ON COLUMN "agent_enrollment_tokens"."server_name" IS 'Tên server sẽ tạo khi node join';

COMMENT ON COLUMN "agent_enrollment_tokens"."expires_at" IS 'Mặc định 1 giờ';

COMMENT ON TABLE "agent_certificates" IS 'Lịch sử chứng chỉ mTLS của node + danh sách thu hồi cho itso-relay (D-89, D-90).';

COMMENT ON COLUMN "agent_certificates"."serial" IS 'Số serial hex do CA nội bộ cấp';

COMMENT ON COLUMN "agent_certificates"."issued_reason" IS 'enroll|rotate|rejoin';

COMMENT ON COLUMN "agent_certificates"."revoked_reason" IS 'revoke|superseded|rejoin';

COMMENT ON TABLE "server_capacity" IS 'Dùng để gợi ý server khi tạo account (D-42) và khóa SELECT FOR UPDATE khi cấp.';

COMMENT ON COLUMN "server_software"."spec_version" IS 'Desired: tăng mỗi lần đổi cấu hình';

COMMENT ON COLUMN "server_software"."observed_version" IS 'Observed: phiên bản agent đã áp dụng';

COMMENT ON COLUMN "server_software"."status" IS 'pending|provisioning|ready|degraded|failed|suspended|deleting';

COMMENT ON COLUMN "php_versions"."spec_version" IS 'Desired: tăng mỗi lần đổi cấu hình';

COMMENT ON COLUMN "php_versions"."observed_version" IS 'Observed: phiên bản agent đã áp dụng';

COMMENT ON COLUMN "php_versions"."status" IS 'pending|provisioning|ready|degraded|failed|suspended|deleting';

COMMENT ON TABLE "uid_allocations" IS 'Dải 20000–59999, không tái dùng trong 90 ngày (D-45).';

COMMENT ON TABLE "hosting_packages" IS 'Gói hosting; giá trị giới hạn nằm ở hosting_package_versions (bất biến, D-43).';

COMMENT ON TABLE "hosting_accounts" IS 'Đơn vị cách ly = 1 Linux user trên 1 server (D-44).';

COMMENT ON COLUMN "hosting_accounts"."lifecycle_state" IS 'pending|provisioning|active|suspended|migrating|terminated|purged|failed';

COMMENT ON COLUMN "hosting_accounts"."spec_version" IS 'Desired: tăng mỗi lần đổi cấu hình';

COMMENT ON COLUMN "hosting_accounts"."observed_version" IS 'Observed: phiên bản agent đã áp dụng';

COMMENT ON COLUMN "hosting_accounts"."status" IS 'pending|provisioning|ready|degraded|failed|suspended|deleting';

COMMENT ON TABLE "account_migrations" IS 'Chuyển account giữa server qua repo restic (D-93): preflight → syncing → verifying → cutover → holding → completed; rollback tới trước dọn dẹp.';

COMMENT ON COLUMN "account_migrations"."state" IS 'preflight|syncing|verifying|cutover|holding|completed|rolled_back|failed';

COMMENT ON COLUMN "account_migrations"."verification" IS 'Danh sách {kind, name, ok, detail}: file sha256, DB, HTTP, SSL, cron, UID';

COMMENT ON COLUMN "account_migrations"."preflight" IS 'Kết quả kiểm tra trước lúc bắt đầu';

COMMENT ON COLUMN "account_migrations"."dns" IS '{mode auto|manual, zone, records[]}';

COMMENT ON COLUMN "account_migrations"."sync_snapshot_id" IS 'Snapshot restic dùng để đồng bộ lượt đầu';

COMMENT ON COLUMN "account_migrations"."final_snapshot_id" IS 'Snapshot lượt cuối lúc cutover';

COMMENT ON TABLE "purge_records" IS 'Biên bản purge (D-46).';

COMMENT ON COLUMN "purge_records"."objects" IS 'đường dẫn, DB, repo, hash';

COMMENT ON COLUMN "websites"."type" IS 'php|static|proxy|docker';

COMMENT ON COLUMN "websites"."ssl_mode" IS 'none|acme|custom';

COMMENT ON COLUMN "websites"."spec_version" IS 'Desired: tăng mỗi lần đổi cấu hình';

COMMENT ON COLUMN "websites"."observed_version" IS 'Observed: phiên bản agent đã áp dụng';

COMMENT ON COLUMN "websites"."status" IS 'pending|provisioning|ready|degraded|failed|suspended|deleting';

COMMENT ON COLUMN "domains"."name" IS 'lowercase punycode';

COMMENT ON COLUMN "domains"."type" IS 'primary|alias|redirect|subdomain';

COMMENT ON COLUMN "website_settings"."custom_snippet" IS 'chỉ SUPER_ADMIN/ADMIN';

COMMENT ON COLUMN "acme_accounts"."key_location" IS 'agent: khóa ACME giữ trên máy do agent quản lý (D-69)';

COMMENT ON COLUMN "acme_accounts"."key_encrypted" IS 'chỉ dùng khi key_location = db';

COMMENT ON COLUMN "certificates"."source" IS 'acme|upload';

COMMENT ON COLUMN "certificates"."private_key_encrypted" IS 'chứng chỉ tải lên: khóa riêng mã hóa (D-69), không đưa vào job';

COMMENT ON COLUMN "certificates"."spec_version" IS 'Desired: tăng mỗi lần đổi cấu hình';

COMMENT ON COLUMN "certificates"."observed_version" IS 'Observed: phiên bản agent đã áp dụng';

COMMENT ON COLUMN "certificates"."status" IS 'pending|provisioning|ready|degraded|failed|suspended|deleting';

COMMENT ON COLUMN "databases"."engine" IS 'mariadb|mysql|postgresql';

COMMENT ON COLUMN "databases"."spec_version" IS 'Desired: tăng mỗi lần đổi cấu hình';

COMMENT ON COLUMN "databases"."observed_version" IS 'Observed: phiên bản agent đã áp dụng';

COMMENT ON COLUMN "databases"."status" IS 'pending|provisioning|ready|degraded|failed|suspended|deleting';

COMMENT ON COLUMN "database_users"."password_encrypted" IS 'mã hóa; job chỉ mang tham chiếu bí mật (D-71)';

COMMENT ON COLUMN "database_users"."spec_version" IS 'Desired: tăng mỗi lần đổi cấu hình';

COMMENT ON COLUMN "database_users"."observed_version" IS 'Observed: phiên bản agent đã áp dụng';

COMMENT ON COLUMN "database_users"."status" IS 'pending|provisioning|ready|degraded|failed|suspended|deleting';

COMMENT ON COLUMN "sftp_accounts"."protocol" IS 'sftp: user Linux của account; ftps: virtual user Pure-FTPd (D-73)';

COMMENT ON COLUMN "sftp_accounts"."password_encrypted" IS 'mã hóa; job chỉ mang tham chiếu bí mật';

COMMENT ON COLUMN "sftp_accounts"."spec_version" IS 'Desired: tăng mỗi lần đổi cấu hình';

COMMENT ON COLUMN "sftp_accounts"."observed_version" IS 'Observed: phiên bản agent đã áp dụng';

COMMENT ON COLUMN "sftp_accounts"."status" IS 'pending|provisioning|ready|degraded|failed|suspended|deleting';

COMMENT ON COLUMN "ssh_keys"."type" IS 'ssh-ed25519|ecdsa-sha2-nistp256|ssh-rsa';

COMMENT ON COLUMN "ssh_keys"."fingerprint" IS 'SHA256:… (base64 không padding)';

COMMENT ON COLUMN "cron_jobs"."spec_version" IS 'Desired: tăng mỗi lần đổi cấu hình';

COMMENT ON COLUMN "cron_jobs"."observed_version" IS 'Observed: phiên bản agent đã áp dụng';

COMMENT ON COLUMN "cron_jobs"."status" IS 'pending|provisioning|ready|degraded|failed|suspended|deleting';

COMMENT ON COLUMN "cron_runs"."status" IS 'running|succeeded|failed|timed_out';

COMMENT ON COLUMN "cron_runs"."trigger" IS 'schedule|manual';

COMMENT ON COLUMN "dns_providers"."type" IS 'cloudflare';

COMMENT ON COLUMN "upload_sessions"."status" IS 'receiving|committing|completed|failed|cancelled';

COMMENT ON COLUMN "file_operations"."op" IS 'write|mkdir|rename|move|copy|delete|chmod|compress|extract|upload';

COMMENT ON COLUMN "file_operations"."status" IS 'queued|running|succeeded|failed';

COMMENT ON COLUMN "terminal_sessions"."mode" IS 'account|root (root: Phase 7)';

COMMENT ON COLUMN "terminal_sessions"."ended_reason" IS 'closed|idle|expired|error';

COMMENT ON TABLE "wordpress_sites" IS 'Site WordPress do Toolkit quản lý (D-99, ADR 0044).';

COMMENT ON COLUMN "wordpress_sites"."path" IS 'Docroot tương đối home account (RelPath); agent kiểm lại sau khi resolve symlink';

COMMENT ON COLUMN "wordpress_sites"."state" IS 'ok|updating|cloning|maintenance|error (D-99)';

COMMENT ON COLUMN "wordpress_sites"."auto_update" IS 'off|minor|all';

COMMENT ON COLUMN "wordpress_sites"."update_window" IS 'HH:00-HH:00 theo giờ server';

COMMENT ON COLUMN "wordpress_sites"."hardening" IS 'file_edit_disabled, xmlrpc_blocked, php_in_uploads_blocked, wp_config_protected, version_hidden, salts_rotated';

COMMENT ON COLUMN "wordpress_sites"."staging_of_id" IS 'Bản staging trỏ về site gốc; đẩy staging → production DEFERRED';

COMMENT ON COLUMN "wordpress_sites"."database_id" IS 'DB của site (DB_NAME trong wp-config); snapshot pre-wp-update gồm DB này';

COMMENT ON COLUMN "wordpress_sites"."last_auto_update_at" IS 'Lần tự cập nhật gần nhất (scheduler chạy tối đa một lần mỗi cửa sổ)';

COMMENT ON TABLE "wordpress_components" IS 'Cache wp.info: core, plugin, theme và bản mới.';

COMMENT ON COLUMN "wordpress_components"."type" IS 'core|plugin|theme';

COMMENT ON COLUMN "wordpress_components"."slug" IS 'null với core; ^[a-z0-9][a-z0-9_-]{0,99}$';

COMMENT ON TABLE "wordpress_updates" IS 'Lịch sử cập nhật an toàn (D-99).';

COMMENT ON COLUMN "wordpress_updates"."trigger" IS 'manual|auto';

COMMENT ON COLUMN "wordpress_updates"."items" IS '[{type, slug, from_version, to_version, ok}]';

COMMENT ON COLUMN "wordpress_updates"."steps" IS 'snapshot|maintenance|update|verify|rollback → done|failed|skipped';

COMMENT ON COLUMN "wordpress_updates"."state" IS 'running|succeeded|rolled_back|failed';

COMMENT ON COLUMN "wordpress_updates"."snapshot_id" IS 'Snapshot pre-wp-update dùng để khôi phục';

COMMENT ON TABLE "git_repositories" IS 'Git deploy theo site (module 22): releases + symlink, rollback.';

COMMENT ON COLUMN "git_repositories"."repo_url" IS 'ssh://git@host/owner/repo.git hoặc https://';

COMMENT ON COLUMN "git_repositories"."deploy_key_public" IS 'ed25519, sinh cho từng site; khóa riêng ở vault của agent';

COMMENT ON COLUMN "git_repositories"."webhook_secret_encrypted" IS 'HMAC-SHA256 cho POST /hooks/git/{token}';

